#![cfg_attr(not(debug_assertions),windows_subsystem="windows")]
mod unit_limits;
use std::{fs,path::PathBuf,time::{Duration,Instant},process::Command};
use eframe::egui;
use sha2::{Digest,Sha256};
struct App { root:PathBuf,troops:u32,unlimited:bool,current:Option<(u32,u32)>,status:String,hash:String,changed:bool,checked:Instant,art:Option<egui::TextureHandle> }
impl App {
 fn new(root:PathBuf)->Self {
  let mut a=Self{root,troops:500,unlimited:false,current:None,status:String::new(),hash:String::new(),changed:false,checked:Instant::now(),art:None};a.refresh();if let Some((t,_))=a.current{a.troops=t;}a.unlimited=fs::read(a.root.join("Praetorians.exe")).ok().and_then(|b|unit_limits::villages(&b).ok()).unwrap_or(false);a
 }
 fn refresh(&mut self){self.checked=Instant::now();match fs::read(self.root.join("Praetorians.exe")){Ok(b)=>{let hash=format!("{:x}",Sha256::digest(&b));if self.hash!=hash{let previous=fs::read_to_string(self.root.join("OpcionesUnidades.ultimo")).unwrap_or_default();self.changed=(!self.hash.is_empty()&&self.hash!=hash)||(!previous.is_empty()&&previous.trim()!=hash);self.hash=hash;}match unit_limits::inspect(&b){Ok(v)=>self.current=Some(v),Err(e)=>{self.current=None;self.status=e}}},Err(e)=>{self.current=None;self.status=e.to_string();}}}
 fn apply(&mut self,t:u32){match unit_limits::apply_options(&self.root,t,self.unlimited){Ok(s)=>{self.refresh();self.changed=false;self.status=s;if let Err(e)=fs::write(self.root.join("OpcionesUnidades.ultimo"),&self.hash){self.status+=&format!(" No se pudo guardar el registro de cambios: {e}");}},Err(e)=>self.status=e}}
 fn launch(&mut self){if unit_limits::running(){self.status="El juego ya está abierto.".into();return}self.refresh();if self.current.is_none(){self.status="No se abre un ejecutable no reconocido.".into();return}self.status=match Command::new(self.root.join("Praetorians.exe")).current_dir(&self.root).spawn(){Ok(_)=>"Juego abierto con los límites actuales.".into(),Err(e)=>format!("No se pudo abrir el juego: {e}")};}
}
fn gold()->egui::Color32{egui::Color32::from_rgb(204,166,95)}
fn card()->egui::Frame{egui::Frame::new().fill(egui::Color32::from_rgb(31,34,39)).stroke(egui::Stroke::new(1_f32,egui::Color32::from_rgb(55,58,62))).corner_radius(12).inner_margin(20.)}
impl eframe::App for App {fn update(&mut self,ctx:&egui::Context,_:&mut eframe::Frame){
 ctx.request_repaint_after(Duration::from_secs(1));if self.checked.elapsed()>=Duration::from_secs(1){self.refresh();}let running=unit_limits::running();
 if self.art.is_none(){self.art=Some(ctx.load_texture("emblema",egui::ColorImage::from_rgba_unmultiplied([256,256],include_bytes!("../assets/emblema.rgba")),Default::default()));}
 egui::SidePanel::left("navigation").exact_width(220.).resizable(false).frame(egui::Frame::new().fill(egui::Color32::from_rgb(19,22,27)).inner_margin(24.)).show(ctx,|ui|{
 ui.add_space(12.);ui.vertical_centered(|ui|{if let Some(a)=&self.art{ui.image((a.id(),egui::vec2(148.,148.)));}ui.add_space(14.);ui.label(egui::RichText::new("PRAETORIANS").size(21.).color(gold()).strong());ui.label(egui::RichText::new("OPCIONES EXTENDIDAS").size(10.).color(egui::Color32::GRAY));});ui.add_space(40.);
 ui.label(egui::RichText::new("EJÉRCITO").color(gold()).size(16.));ui.add_space(12.);ui.label("Límites de tropas y grupos");
 ui.with_layout(egui::Layout::bottom_up(egui::Align::LEFT),|ui|{ui.small("MODS COMPLEX · UTILIDAD");ui.add_space(10.);ui.label(egui::RichText::new("Tu ejército. Tus reglas.").color(gold()));});});
 egui::TopBottomPanel::bottom("actions").frame(egui::Frame::new().fill(egui::Color32::from_rgb(24,27,32)).inner_margin(egui::Margin::symmetric(28,18))).show(ctx,|ui|{ui.horizontal(|ui|{if ui.add_enabled(!running&&self.current.is_some(),egui::Button::new(egui::RichText::new("Aplicar cambios").color(egui::Color32::from_rgb(25,24,21)).strong()).fill(gold()).min_size(egui::vec2(170.,42.)).corner_radius(8)).clicked(){self.apply(self.troops);}ui.add_space(8.);if ui.add_enabled(!running,egui::Button::new("Abrir juego").min_size(egui::vec2(130.,42.)).corner_radius(8)).clicked(){self.launch();}ui.label(if running{"Juego abierto"}else{"Usa partidas nuevas"});});if !self.status.is_empty(){ui.add_space(8.);ui.label(&self.status);}});
 egui::CentralPanel::default().frame(egui::Frame::new().fill(egui::Color32::from_rgb(25,28,33)).inner_margin(30.)).show(ctx,|ui|{egui::ScrollArea::vertical().show(ui,|ui|{
 ui.label(egui::RichText::new("CONFIGURACIÓN DEL EJÉRCITO").size(11.).color(gold()));ui.add_space(8.);ui.heading(egui::RichText::new("Límites de batalla").size(30.));ui.add_space(8.);ui.label(egui::RichText::new("Ajusta el máximo de tropas y grupos por jugador.").color(egui::Color32::from_gray(160)));ui.add_space(24.);
 if self.changed{ui.colored_label(gold(),"Mod Complex ha cambiado el ejecutable. Revisa los límites antes de reaplicarlos.");ui.add_space(12.);}
 card().show(ui,|ui|{ui.set_min_width(ui.available_width());ui.label(egui::RichText::new("ACTUALMENTE APLICADO").size(10.).color(egui::Color32::GRAY));ui.add_space(6.);ui.label(egui::RichText::new(match self.current{Some((t,g))=>format!("{t} tropas   /   {g} grupos"),None=>"Ejecutable no compatible".into()}).size(23.).color(gold()));});ui.add_space(20.);
for (t,g,title,desc)in [(500,50,"Clásico","Los límites originales de Praetorians."),(750,75,"Batalla grande","Más margen para ampliar tu ejército."),(1000,100,"Batalla masiva","El mayor límite disponible en esta utilidad.")]{let chosen=self.troops==t;let frame=card().stroke(egui::Stroke::new(1_f32,if chosen{gold()}else{egui::Color32::from_gray(55)}));let response=frame.show(ui,|ui|{ui.set_min_width(ui.available_width());ui.horizontal(|ui|{ui.radio_value(&mut self.troops,t,"");ui.vertical(|ui|{ui.label(egui::RichText::new(title).size(19.).strong());ui.label(egui::RichText::new(desc).size(12.).color(egui::Color32::GRAY));});ui.with_layout(egui::Layout::right_to_left(egui::Align::Center),|ui|{ui.label(egui::RichText::new(format!("{t} / {g}")).size(21.).color(if chosen{gold()}else{egui::Color32::from_gray(190)}));});});});if response.response.interact(egui::Sense::click()).clicked(){self.troops=t;}ui.add_space(10.);}ui.add_space(6.);if ui.add_enabled(!running&&self.current.is_some(),egui::Button::new("Restaurar límite original · 500 / 50").frame(false)).clicked(){self.troops=500;self.apply(500);}
 ui.add_space(12.);card().show(ui,|ui|{ui.set_min_width(ui.available_width());ui.checkbox(&mut self.unlimited,egui::RichText::new("Población inagotable en las aldeas").size(18.));ui.add_space(8.);ui.label("El reclutamiento no consume población. Se aplica a jugadores e IA.");ui.small("La aldea debe disponer de población suficiente para aceptar el pedido. Cancelarlo no añade habitantes. Mantiene los demás costes y límites.");});
 ui.add_space(14.);ui.small(self.root.to_string_lossy());
 });});}}
fn main()->eframe::Result{let folder=std::env::current_exe().unwrap().parent().unwrap().to_owned();let args:Vec<_>=std::env::args().collect();let root=args.iter().position(|a|a=="--game-dir").and_then(|i|args.get(i+1)).map(PathBuf::from).unwrap_or_else(||if folder.join("Praetorians.exe").exists(){folder.clone()}else{PathBuf::from("C:/Games/Praetorians")});if let Some(i)=args.iter().position(|s|s=="--apply"){let result=args.get(i+1).and_then(|s|s.parse().ok()).ok_or("Falta el límite".to_owned()).and_then(|t|unit_limits::apply(&root,t));let _=fs::write(folder.join("OpcionesUnidades.log"),match result{Ok(s)=>s,Err(e)=>{let _=fs::write(folder.join("OpcionesUnidades.error"),&e);e}});return Ok(())}eframe::run_native("Opciones extendidas",eframe::NativeOptions{viewport:egui::ViewportBuilder::default().with_icon(egui::IconData{rgba:include_bytes!("../assets/icono-64.rgba").to_vec(),width:64,height:64}).with_inner_size([940.,920.]).with_min_inner_size([940.,920.]),..Default::default()},Box::new(move|cc|{cc.egui_ctx.set_visuals(egui::Visuals::dark());cc.egui_ctx.style_mut(|s|{s.spacing.item_spacing=egui::vec2(10.,8.);s.spacing.button_padding=egui::vec2(14.,10.);});Ok(Box::new(App::new(root)))}))}
